const roster = document.querySelector('#roster');
roster.innerHTML = eclipseMembers.map((member, index) => {
  const initials = String(index + 1).padStart(2, '0');
  const socialLinks = Object.entries(member.links).map(([platform, url]) =>
    `<a class="social-link" href="${url}" target="_blank" rel="noopener" aria-label="${platform} — رابط ${member.name}" title="${platform}">${icons[platform]}</a>`
  ).join('');
  return `<article class="member-card">
    <div class="portrait-wrap" role="img" aria-label="مساحة صورة ${member.name}">
      <img class="portrait-photo" src="${member.portrait}" alt="${member.name}" onload="this.parentElement.querySelector('.portrait-glyph').style.display='none'; this.parentElement.querySelector('.portrait-caption').style.display='none'" onerror="this.style.display='none'">
      <span class="portrait-glyph">${initials}</span>
      <span class="portrait-caption">أضف الصورة هنا</span>
    </div>
    <div class="member-meta">
      <h3 class="member-name" dir="ltr">${member.name}</h3>
      <p class="member-bio">${member.bio}</p>
      <div class="social-row" aria-label="روابط ${member.name}">${socialLinks}</div>
    </div>
  </article>`;
}).join('');

